//
// The device keys: one Ed25519 key per provider, generated by WebCrypto as a non-extractable
// CryptoKey and kept in IndexedDB. The private half never exists as bytes anywhere the
// extension's code or a storage export could read it; the key signs the sign-in, every vote,
// the session refresh and the account's deletion.

import { createIdbHandle, runTransaction } from "./idb-open";

// Exported so a browser test can tear the database down by name.
export const DEVICE_KEYS_DB_NAME = "emojery-device-keys";
const STORE = "keys";

const db = createIdbHandle(DEVICE_KEYS_DB_NAME, 1, (d) => {
  if (!d.objectStoreNames.contains(STORE)) d.createObjectStore(STORE, { keyPath: "provider" });
});

interface DeviceKeyRow {
  provider: string;
  privateKey: CryptoKey;
  publicKey: Uint8Array;
  createdAt: number;
}

/** What leaves this module: the public key; signing goes through signWithDeviceKey. */
export interface DeviceKey {
  provider: string;
  publicKey: Uint8Array;
}

async function generate(provider: string): Promise<DeviceKeyRow> {
  const pair = (await crypto.subtle.generateKey({ name: "Ed25519" }, false, ["sign", "verify"])) as CryptoKeyPair;
  const publicKey = new Uint8Array((await crypto.subtle.exportKey("raw", pair.publicKey)) as ArrayBuffer);
  return { provider, privateKey: pair.privateKey, publicKey, createdAt: Date.now() };
}

async function readRow(provider: string): Promise<DeviceKeyRow | undefined> {
  return runTransaction(await db.open(), STORE, "readonly", "device key read aborted", (store) => {
    const req = store.get(provider);
    return () => req.result as DeviceKeyRow | undefined;
  });
}

/** The provider's device key, generated on first use. Two concurrent asks settle inside one
 *  transaction, so the second keeps the first one's key. */
export async function ensureDeviceKey(provider: string): Promise<DeviceKey> {
  const fresh = await generate(provider);
  const row = await runTransaction(await db.open(), STORE, "readwrite", "device key write aborted", (store) => {
    let kept = fresh;
    const req = store.get(provider);
    req.onsuccess = () => {
      const existing = req.result as DeviceKeyRow | undefined;
      if (existing) kept = existing;
      else store.put(fresh);
    };
    return () => kept;
  });
  return { provider: row.provider, publicKey: row.publicKey };
}

export async function getDeviceKey(provider: string): Promise<DeviceKey | null> {
  const row = await readRow(provider);
  return row ? { provider: row.provider, publicKey: row.publicKey } : null;
}

/** A fresh key for the provider, replacing the old one (a failed registration, a key the
 *  server no longer knows). */
export async function replaceDeviceKey(provider: string): Promise<DeviceKey> {
  const fresh = await generate(provider);
  await runTransaction(await db.open(), STORE, "readwrite", "device key replace aborted", (store) => {
    store.put(fresh);
    return () => undefined;
  });
  return { provider: fresh.provider, publicKey: fresh.publicKey };
}

export async function dropDeviceKey(provider: string): Promise<void> {
  await runTransaction(await db.open(), STORE, "readwrite", "device key delete aborted", (store) => {
    store.delete(provider);
    return () => undefined;
  });
}

/** Ed25519 over `message` with the provider's key; throws when the provider has none. */
export async function signWithDeviceKey(provider: string, message: Uint8Array): Promise<Uint8Array> {
  const row = await readRow(provider);
  if (!row) throw new Error(`no device key for ${provider}`);
  return new Uint8Array(await crypto.subtle.sign("Ed25519", row.privateKey, message as BufferSource));
}
